package com.sathavahana.kalamkari.dto; import com.sathavahana.kalamkari.domain.Product; import java.math.BigDecimal; public record ProductDto(Long id,String slug,String name,String description,BigDecimal price,int stockQuantity,Long categoryId,String categoryName,String imageUrl){public static ProductDto of(Product p){return new ProductDto(p.getId(),p.getSlug(),p.getName(),p.getDescription(),p.getPrice(),p.getStockQuantity(),p.getCategory()==null?null:p.getCategory().getId(),p.getCategory()==null?null:p.getCategory().getName(),p.getImageUrl());}}
